#pragma once
#include "engine/lighting/Providers.hpp"
inline Engine::Result BuildLightingScenario(Engine::Scene::World& world,Engine::Scene::CommandHistory& history,const std::filesystem::path& hdri){
    using namespace Engine;using namespace Scene;
    std::vector<EntityDefinition> entities;entities.reserve(1005);EntityDefinition settings;settings.id={30,1};settings.name.value="Lighting environment / fog / exposure";
    ModuleComponent component;DefaultComponent(Lighting::kEnvironmentSettings,component);component.fields[0]=std::uint32_t(1);component.fields[1]=Vec3{30,30,30};component.fields[3]=hdri.string();settings.extensions.push_back(component);DefaultComponent(Lighting::kFogSettings,component);component.fields[1]=.015f;component.fields[4]=Vec3{100,120,140};settings.extensions.push_back(component);DefaultComponent(Lighting::kExposureSettings,component);component.fields[3]=10.f;component.fields[4]=5.f;settings.extensions.push_back(component);entities.push_back(settings);
    for(std::uint32_t i=0;i<1000;++i){EntityDefinition light;light.id={31,i+1};light.name.value="Cluster point "+std::to_string(i);light.transform.position={float(i%10)*1.5f-7,float((i/10)%10)*1.5f-4,float(i/100)*-1.5f+5};Lighting::PointLight point;point.intensity=250;point.range=.8f;point.common.castShadows=0;point.common.color={float(i%3==0),float(i%3==1),float(i%3==2)};Lighting::Encode(Lighting::kPointLight,&point,component);light.extensions.push_back(component);entities.push_back(light);}
    EntityDefinition spot;spot.id={32,1};spot.name.value="Shadowed spot";spot.transform.position={0,5,6};spot.transform.rotation={-.5f,0,0};Lighting::SpotLight cone;cone.intensity=10000;cone.range=25;Lighting::Encode(Lighting::kSpotLight,&cone,component);spot.extensions.push_back(component);entities.push_back(spot);
    EntityDefinition point;point.id={32,2};point.name.value="Shadowed point";point.transform.position={-3,2,2};Lighting::PointLight bulb;bulb.intensity=800;bulb.range=8;bulb.common.shadowResolution=256;Lighting::Encode(Lighting::kPointLight,&bulb,component);point.extensions.push_back(component);entities.push_back(point);
    for(std::uint32_t i=0;i<6;++i){EntityDefinition shadow;shadow.id={33,i+1};shadow.name.value="Cached shadow point "+std::to_string(i);shadow.transform.position={float(i%3)*3-3,3,float(i/3)*4-2};Lighting::PointLight source;source.intensity=400;source.range=8;source.common.shadowResolution=256;Lighting::Encode(Lighting::kPointLight,&source,component);shadow.extensions.push_back(component);entities.push_back(shadow);}
    EntityDefinition rect;rect.id={32,3};rect.name.value="LTC rectangle";rect.transform.position={3,2,5};Lighting::RectLight panel;panel.intensity=2000;panel.width=2;panel.height=1;Lighting::Encode(Lighting::kRectLight,&panel,component);rect.extensions.push_back(component);entities.push_back(rect);
    EntityDefinition disk;disk.id={32,4};disk.name.value="LTC disk";disk.transform.position={-3,2,5};Lighting::DiskLight circle;circle.intensity=2000;circle.radius=1;Lighting::Encode(Lighting::kDiskLight,&circle,component);disk.extensions.push_back(component);entities.push_back(disk);
    return history.Execute(world,std::make_unique<EntityBatchCommand>(std::move(entities),std::vector<Guid>{}));
}
